typedef unsigned int uint32;

enum { WAVE_REGIONTUBE = 9 };

class board_controller {
public:
  char pad0[0x460];
  int inAirFlag;
  char pad1[0xDA0 - 0x464];
  int wiped_out;
  char pad2[0xDE0 - 0xDA4];
  int region;

  int GetRegion() { return region; }
  int WipedOut() { return wiped_out; }
};

class kellyslater_controller {
public:
  char pad0[0x30];
  int current_state;
  char pad1[4];
  int super_state;
  char pad2[0x218 - 0x3C];
  short current_anim;
  char pad3[0x224 - 0x21A];
  unsigned char current_board_anim;
  char pad4[0x460 - 0x225];
  int in_air;
  char pad5[0xDA0 - 0x464];
  int wiped_out;
  char pad6[0xDE0 - 0xDA4];
  int region;
  char pad7[0x1690 - 0xDE4];
  int ik_valid;
  char pad8[0x19FC - 0x1694];
  int dry;

  int get_current_state() { return current_state; }
  int get_super_state() { return super_state; }
  int GetCurrentAnim() { return current_anim; }
  int GetCurrentBoardAnim() { return current_board_anim; }
  int GetCurrentTrick();
  board_controller &get_board_controller() { return *(board_controller *)this; }
  int isDry() { return dry; }
  int get_ik_valid() { return ik_valid; }
};

class world_dynamics_system {
public:
  char pad[0xF8];
  kellyslater_controller *controllers[2];

  kellyslater_controller *get_ks_controller(int player) {
    return controllers[player];
  }
};

extern world_dynamics_system *g_world_ptr;

class KSEntityState
{
private:
  uint32 KSState          : 7;
  uint32 KSSuperState     : 4;
  uint32 KSAnim           : 10;
  uint32 KSBAnim          : 8;

  uint32 KSBlend          : 7;
  uint32 KSBBlend         : 7;
  uint32 KSCurTrick       : 7;

  uint32 KSAnimCall       : 1;
  uint32 KSBAnimCall      : 1;
  uint32 KSLoop           : 1;
  uint32 KSBLoop          : 1;
  uint32 KSWipedOut       : 1;
  uint32 KSInAir          : 1;
  uint32 KSInTube         : 1;
  uint32 KSDry            : 1;
  uint32 KSIKValid        : 1;
  uint32 KSWipeoutSplash  : 1;
  uint32 EndWave          : 1;

  uint32 padding          : 3;

public:
  void Save( int player );
};

void KSEntityState::Save( int player )
{
  // Grab the surfer state
  KSState   = g_world_ptr->get_ks_controller(player)->get_current_state();
  KSSuperState = g_world_ptr->get_ks_controller(player)->get_super_state();

  // Grab anim info
  KSAnim    = g_world_ptr->get_ks_controller(player)->GetCurrentAnim();
  KSBAnim   = g_world_ptr->get_ks_controller(player)->GetCurrentBoardAnim();

  KSCurTrick = g_world_ptr->get_ks_controller(player)->GetCurrentTrick();

  // Grab frame info
  //KSFrame   = g_world_ptr->get_ks_controller(player)->GetCurrentFrame();
  //KSBFrame  = g_world_ptr->get_ks_controller(player)->GetBoardAnimTime();

  // Grab various flags
  KSInAir     = g_world_ptr->get_ks_controller(player)->get_board_controller().inAirFlag;
  KSInTube    = g_world_ptr->get_ks_controller(player)->get_board_controller().GetRegion() == WAVE_REGIONTUBE;
  KSDry       = g_world_ptr->get_ks_controller(player)->isDry();
  KSIKValid   = g_world_ptr->get_ks_controller(player)->get_ik_valid();
  KSWipedOut  = g_world_ptr->get_ks_controller(player)->get_board_controller().WipedOut ();
}
